content.text:
{
  "name": "FPGA寄存器通信接口",
  "name_en": "FPGA Register Communication Interface",
  "manufacturer": "",
  "description": "用于通过 USB 与 FPGA 设备进行寄存器级读写的非物理软件接口组件。它在实验系统中提供底层地址访问、连接状态检查以及获取底层设备对象的能力，适合用于控制或调试依赖 FPGA 的仪器模块。",
  "description_en": "A non-physical software interface component for register-level communication with an FPGA over USB. In laboratory systems, it provides low-level address read/write access, connection checking, and access to the underlying device object, making it useful for controlling or debugging FPGA-based instrument modules.",
  "actions": [
    {
      "action_name": "auto-is_connected",
      "description": "检查该通信接口是否已连接到 USB 端口。",
      "description_en": "Check whether this communication interface is connected to a USB port."
    },
    {
      "action_name": "auto-get_device",
      "description": "获取该接口当前关联的底层设备对象。",
      "description_en": "Get the underlying device object associated with this interface."
    },
    {
      "action_name": "auto-write",
      "description": "向指定地址写入数值，以执行 FPGA 的底层寄存器写操作。",
      "description_en": "Write a value to a specified address to perform a low-level FPGA register write."
    },
    {
      "action_name": "auto-read",
      "description": "从指定地址读取数据，以执行 FPGA 的底层寄存器读操作。",
      "description_en": "Read data from a specified address to perform a low-level FPGA register read."
    }
  ],
  "tag_hints": [
    "FPGA register access",
    "USB communication",
    "low-level hardware interface",
    "memory-mapped I/O",
    "device connectivity check",
    "instrument control support"
  ]
}

